import './navigation.js';
import {storageLoad,storageSave,createSeed,createBlankSchool,isoDate,weekday} from './data.js';
import {translate,setupWords,progressWords} from './i18n.js';
let db=storageLoad(),role=sessionStorage.getItem('ss-role')||'',screen=sessionStorage.getItem('ss-screen')||'welcome',person=sessionStorage.getItem('ss-person')||'',child=sessionStorage.getItem('ss-child')||'',currentClass=sessionStorage.getItem('ss-currentClass')||'4a',editing=sessionStorage.getItem('ss-editing')||'',editLesson=sessionStorage.getItem('ss-editLesson')||'',filterClass='all',filterType='all',query='',weekOffset=0,selectedDate=isoDate();
const el=document.getElementById('app');const t=k=>progressWords[db.settings.language]?.[k]||translate(db.settings.language,k);const st=k=>setupWords[db.settings.language]?.[k]||setupWords.en[k]||k;const demoOn=()=>db.settings.demo!==false;const locale=()=>({en:'en-GB',ar:'ar-IL',he:'he-IL'})[db.settings.language];const rtl=()=>db.settings.language!=='en';const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(v,extra='')=>`<span lang="${db.settings.language}" dir="${rtl()?'rtl':'ltr'}" class="localized ${extra}">${E(v)}</span>`;const date=d=>d?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',year:'numeric',numberingSystem:'latn'}).format(new Date(d+'T12:00:00')):'—';const n=x=>new Intl.NumberFormat(locale(),{numberingSystem:'latn'}).format(x);const sub=s=>t(s)||s;const nameClass=id=>db.classes.find(c=>c.id===id)?.name||id;const teacherName=id=>db.teachers.find(u=>u.id===id)?.name||'—';const student=()=>db.students.find(s=>s.id===person)||db.students[0];const parent=()=>db.parents.find(p=>p.id===person)||db.parents[0];const teacher=()=>db.teachers.find(p=>p.id===person)||db.teachers[0];const activeStudent=()=>db.students.find(s=>s.id===child)||db.students.find(s=>s.id===parent().studentIds[0])||db.students[0];const assignments=()=>teacher().assignments;const permitted=(cl,subject)=>assignments().some(a=>a.classId===cl&&(!subject||a.subject===subject));const myClasses=()=>[...new Set(assignments().map(a=>a.classId))];const people=()=>role==='student'?db.students:role==='parent'?db.parents:db.teachers;const now=()=>new Date().getHours()<15?t('goodMorning'):t('goodEvening');const classUpdates=cl=>db.updates.filter(u=>u.classId===cl&&u.status==='published');const updatesFor=s=>classUpdates(s.classId);const homeworkFor=s=>updatesFor(s).filter(u=>u.type==='homework');const completion=(s,u)=>!!db.completions[s.id+'|'+u.id];const lessons=(cl,day)=>db.lessons.filter(l=>l.classId===cl&&l.day===day).sort((a,b)=>a.start.localeCompare(b.start));
const icons={home:'house',timetable:'calendar-days',homework:'book-open-check',bag:'backpack',week:'calendar-range',progress:'chart-no-axes-column',children:'users-round',childDetail:'user-round',announcements:'message-square-text',calendar:'calendar-days',tomorrow:'sunrise',classes:'school',classDetail:'book-open',create:'square-pen',edit:'pen-line',manage:'list-checks',schedule:'calendar-clock',history:'history',settings:'settings',language:'languages',notifications:'bell',help:'circle-help',student:'graduation-cap',parent:'heart-handshake',teacher:'presentation',mathematics:'sigma',science:'flask-conical',english:'languages',arabic:'book-open',hebrew:'book-type',sports:'activity',art:'palette',test:'clipboard-check',announcement:'megaphone',event:'calendar-heart',reminder:'pin',supplies:'package',check:'check',clock:'clock-3',arrow:'arrow-right',plus:'plus',trash:'trash-2',editIcon:'pencil',chevron:'chevron-right',shield:'shield-check',spark:'sparkles',book:'book-open',users:'users',close:'x',filter:'sliders-horizontal'};
const path=(key)=>({house:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',check:'<path d="m5 12 4 4L19 6"/>',sigma:'<path d="M18 4H6l7 8-7 8h12"/>',backpack:'<rect x="5" y="7" width="14" height="15" rx="4"/><path d="M9 7V5a3 3 0 0 1 6 0v2M5 14h14M10 17h4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v6M14 11v6"/>',pen:'<path d="m4 20 4.5-1 11-11-3.5-3.5-11 11zM14 6l4 4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',book:'<path d="M12 6c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1zM12 6v15"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5"/>',generic:'<rect x="4" y="4" width="16" height="16" rx="5"/><path d="M8 12h8"/>'})[key]||'';
function ic(key,size=19){let slug=icons[key]||key;let simp={ 'calendar-days':'calendar','calendar-range':'calendar','calendar-clock':'calendar','calendar-heart':'calendar','sunrise':'calendar','chart-no-axes-column':'generic','book-open-check':'book','book-open':'book','book-type':'book','flask-conical':'generic','graduation-cap':'book','heart-handshake':'users','presentation':'users','school':'generic','users-round':'users','user-round':'users','message-square-text':'generic','square-pen':'pen','pen-line':'pen','pencil':'pen','list-checks':'check','history':'clock','settings':'generic','languages':'book','circle-help':'generic','package':'generic','clipboard-check':'check','megaphone':'generic','pin':'generic','activity':'generic','palette':'generic','shield-check':'check','sparkles':'generic','sliders-horizontal':'generic','chevron-right':'arrow'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path(simp[slug]||slug)||path('generic')}</svg>`}
function button(key,action,kind='primary',icon=''){let label=setupWords[db.settings.language]?.[key]||t(key);return `<button type="button" class="btn ${kind}" data-action="${action}">${icon?ic(icon):''}${txt(label)}</button>`}function section(title,content,action='',extra=''){return `<section class="panel ${extra}"><div class="panel-header"><h2>${txt(t(title))}</h2>${action}</div>${content}</section>`}function empty(k='noTasks'){return `<div class="empty"><span class="empty-icon">${ic('book',26)}</span>${txt(t(k))}</div>`}function chip(label,color='lavender'){return `<span class="chip ${color}">${txt(label)}</span>`}function labelClass(cl){return txt(nameClass(cl))}function subjectIcon(key){return `<span class="subject-icon ${key}">${ic(key,22)}</span>`}function notice(type,msg){const a=document.getElementById('toast');a.textContent=msg||t(type);a.className='visible '+type;clearTimeout(window.__toast);window.__toast=setTimeout(()=>a.className='',3200)}function save(){if(!storageSave(db))notice('error',t('saveError'))}function go(s){screen=s;sessionStorage.setItem('ss-screen',s);render();window.scrollTo({top:0,behavior:'instant'})}function switchRole(r,p){role=r;person=p||((r==='student'?db.students:r==='parent'?db.parents:db.teachers)[0].id);child=r==='parent'?db.parents.find(x=>x.id===person)?.studentIds[0]||'':'';sessionStorage.setItem('ss-role',role);sessionStorage.setItem('ss-person',person);sessionStorage.setItem('ss-child',child);go('home')}
const menus={student:['home','timetable','homework','bag','week','progress'],parent:['home','children','childDetail','progress','homework','announcements','calendar','tomorrow'],teacher:['home','classes','classDetail','create','manage','schedule','history']};
function shell(content){const items=menus[role]||[];const pageTitle=screen==='home'?(role==='student'?t('morning'):t('overview')):t(screen);const principal=people().find(x=>x.id===person)||people()[0];const full=[...items,'notifications','settings','language','help'];return `<div class="app-shell"><aside class="sidebar"><button class="logo" data-action="go:home" aria-label="SCHOOL SIGNAL home"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span><small>${txt(t('brand'))}</small></span></button><div class="side-section-label">${txt(t(role))} · ${txt(t('demo'))}</div><nav aria-label="Main navigation">${full.map(x=>`<button class="nav-link ${screen===x?'active':''}" data-action="go:${x}" ${screen===x?'aria-current="page"':''}>${ic(x)}${txt(t(x))}${x==='notifications'&&unreadCount()?`<span class="nav-count">${unreadCount()}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="profile-mini"><span class="avatar">${E(principal.name.slice(0,1))}</span><span><strong>${E(principal.name)}</strong><small>${txt(t(role))}</small></span></div>${button('logout','switch','ghost','users')}</div></aside><div class="main-area"><header class="topbar"><div class="mobile-brand"><span class="signal-mark"><i></i><i></i><i></i></span><strong>SCHOOL SIGNAL</strong></div><div class="breadcrumbs">${txt(t(role))}<span class="crumb-sep">/</span><b>${txt(pageTitle)}</b></div><div class="top-actions"><span class="demo-pill">${txt(t('demo'))}</span><button class="icon-button" data-action="go:notifications" aria-label="${E(t('notifications'))}">${ic('notifications',21)}${unreadCount()?'<i class="notif-dot"></i>':''}</button><select id="lang-select" class="compact-select" aria-label="${E(t('language'))}">${Object.entries({ar:'العربية',he:'עברית',en:'English'}).map(([k,v])=>`<option value="${k}" ${db.settings.language===k?'selected':''}>${v}</option>`).join('')}</select></div></header><main id="content" class="content" tabindex="-1">${content}<footer>${txt(t('syncDisclaimer'))}</footer></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${[...items.slice(0,4),'settings'].map(x=>`<button data-action="go:${x}" class="${screen===x?'active':''}">${ic(x,21)}<small>${txt(t(x))}</small></button>`).join('')}</nav></div>`}
function publicPage(){if(screen==='welcome')return `<div class="public"><header class="public-bar"><div class="logo static-logo"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span></span></div><select id="lang-select" aria-label="${E(t('language'))}" class="compact-select">${Object.entries({ar:'العربية',he:'עברית',en:'English'}).map(([k,v])=>`<option value="${k}" ${db.settings.language===k?'selected':''}>${v}</option>`).join('')}</select></header><div class="welcome-layout"><div class="welcome-copy"><span class="eyebrow">SCHOOL SIGNAL · DAY 29</span><h1>${txt(t('welcome'))}</h1><p>${txt(t('welcomeSub'))}</p>${button('enter','go:choose','primary','arrow')}<div class="welcome-foot">${txt(t('tagline'))}</div></div><div class="welcome-art" aria-hidden="true"><div class="sample-sheet"><div class="sheet-head"><span class="dot-logo">S</span><span class="line wide"></span><span class="tiny-circle"></span></div><div class="sheet-title"></div><div class="sheet-sub"></div><div class="sheet-cards"><div><span class="mini-symbol">${ic('timetable',30)}</span><span class="line"></span><span class="line short"></span></div><div><span class="mini-symbol">${ic('bag',30)}</span><span class="line"></span><span class="line short"></span></div></div><div class="sheet-check">${ic('check',26)}<span class="line wide"></span></div></div><div class="floating-note">${ic('bell',21)}<span class="line wide"></span></div></div></div></div>`;if(screen==='choose')return `<div class="public"><header class="public-bar"><div class="logo static-logo"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span></span></div>${button('back','go:welcome','ghost')}</header><div class="public-center"><span class="eyebrow">SCHOOL SIGNAL</span><h1>${txt(t('choose'))}</h1><p>${txt(t('chooseSub'))}</p><div class="role-grid">${['student','parent','teacher'].map((r,i)=>`<button class="role-choice" data-action="selectRole:${r}"><span class="role-symbol role-${r}">${ic(r,34)}</span><h2>${txt(t(r))}</h2><p>${txt(t(r+'Desc'))}</p><span class="role-arrow">${ic('arrow')}</span></button>`).join('')}</div><div class="demo-callout">${ic('shield',20)}${txt(t('demoNote'))}</div></div></div>`;return `<div class="public"><header class="public-bar"><div class="logo static-logo"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span></span></div>${button('back','go:choose','ghost')}</header><div class="public-center onboarding"><span class="eyebrow">${txt(t('demo'))}</span><h1>${txt(t('demoWelcome'))}</h1><p>${txt(t('demoText'))}</p><div class="panel form-panel"><label>${txt(t('profile'))}<select id="person-select">${people().map(p=>`<option value="${p.id}" ${person===p.id?'selected':''}>${E(p.name)}${p.classId?' · '+nameClass(p.classId):''}</option>`).join('')}</select></label><div class="soft-info">${ic('shield',22)}${txt(t('demoNote'))}</div>${button('getStarted','start','primary','arrow')}</div></div></div>`}
function activeNotifications(){if(role==='teacher')return db.updates.filter(u=>u.teacherId===person).sort((a,b)=>b.id.localeCompare(a.id));let sts=role==='student'?[student()]:parent().studentIds.map(id=>db.students.find(s=>s.id===id)).filter(Boolean);return db.updates.filter(u=>u.status==='published'&&sts.some(s=>s.classId===u.classId)).sort((a,b)=>b.id.localeCompare(a.id))}function unreadCount(){return role==='teacher'?0:activeNotifications().filter(u=>!db.read[person+'|'+u.id]).length}
function header(title,desc='',action=''){return `<div class="page-intro"><div><span class="eyebrow">${txt(t('demo'))} · SCHOOL SIGNAL</span><h1>${txt(title)}</h1>${desc?`<p>${txt(desc)}</p>`:''}</div>${action?`<div class="page-cta">${action}</div>`:''}</div>`}
function greetingHeader(name,desc,action=''){return `<div class="page-intro centered-intro"><div><h1 lang="${db.settings.language}" dir="${rtl()?'rtl':'ltr'}"><span class="localized">${E(now())}</span><bdi dir="auto">${E(name)}</bdi></h1>${desc?`<p>${txt(desc)}</p>`:''}</div>${action?`<div class="page-cta">${action}</div>`:''}</div>`}
function stat(value,label,icon,color='lavender'){return `<div class="stat"><span class="stat-icon ${color}">${ic(icon,22)}</span><div><strong>${E(value)}</strong><span>${txt(t(label))}</span></div></div>`}
function countDone(s){let hw=homeworkFor(s);return [hw.filter(u=>completion(s,u)).length,hw.length]}
function timetable(s,day=weekday(isoDate())){let ls=lessons(s.classId,day);return ls.length?`<div class="lesson-list">${ls.map((l,i)=>`<div class="lesson-row"><div class="lesson-time" dir="ltr"><strong>${E(l.start)}</strong><small>${E(l.end)}</small></div>${subjectIcon(l.subject)}<div class="lesson-copy"><strong>${txt(t(l.subject))}</strong><small>${txt(l.room||teacherName(l.teacherId))}</small></div><span class="lesson-index">${n(i+1)}</span></div>`).join('')}</div>`:empty('noLessons')}
function updateCard(u,s=null){let completed=s&&completion(s,u);return `<article class="update-row"><span class="update-symbol ${u.type}">${ic(u.type==='homework'?'homework':u.type,21)}</span><div class="update-body"><div class="update-meta">${chip(t(u.type==='supplies'?'suppliesType':u.type+'Type'),u.type==='homework'?'lavender':u.type==='test'?'peach':'sky')}${chip(t(u.subject),'plain')}${role==='parent'?chip(nameClass(u.classId),'plain'):''}</div><strong class="record-title" dir="auto">${E(u.title)}</strong><p dir="auto">${E(u.description)}</p><div class="record-details">${ic('clock',15)}<span>${txt(t('due'))}: <bdi dir="auto">${E(date(u.due))}</bdi></span><span>· ${E(teacherName(u.teacherId))}</span></div></div>${s&&u.type==='homework'?`<button class="completion-button ${completed?'done':''}" data-action="complete:${s.id}:${u.id}" aria-pressed="${completed}">${ic('check',17)}${txt(t(completed?'undo':'markDone'))}</button>`:''}${role==='teacher'&&u.teacherId===person?`<button class="icon-button" data-action="edit:${u.id}" aria-label="${E(t('edit'))}">${ic('editIcon')}</button>`:''}</article>`}
function visibleBag(s,d=isoDate()){const daily=lessons(s.classId,weekday(d));const defaults=[{key:'water',id:'base-water',value:t('water')},{key:'pencil',id:'base-pencil',value:t('pencil')}];const subjNeeded=[...new Set(daily.map(l=>l.subject))].filter(x=>!['sports','art'].includes(x)).map(x=>({id:'subject-'+x,value:t(x)+' — '+t('book')}));const extra=daily.some(l=>l.subject==='sports')?[{id:'sport-clothes',value:db.settings.language==='ar'?'لبس رياضة':db.settings.language==='he'?'בגדי ספורט':'Sports clothes'}]:[];const supplied=updatesFor(s).filter(u=>u.supplies?.length&&u.due>=d&&u.due<=isoDate(8)).flatMap(u=>u.supplies.map(v=>({id:'supply-'+v.toLowerCase().trim(),value:v})));let manually=(db.extraBag?.[s.id+'|'+d]||[]).map((v,i)=>({id:'manual-'+i,value:v}));return [...new Map([...defaults,...subjNeeded,...extra,...supplied,...manually].map(v=>[v.value.toLowerCase(),v])).values()]}
function packedCount(s,d=isoDate()){let items=visibleBag(s,d);return [items.filter(x=>db.packed[s.id+'|'+d+'|'+x.id]).length,items.length]}
function bagList(s,d=isoDate(),allow=true){let items=visibleBag(s,d),[done,total]=packedCount(s,d);return `<div class="bag-progress"><div class="progress-top"><strong>${n(done)} / ${n(total)}</strong><span>${txt(t('packed'))}</span></div><div class="progress-track"><span style="width:${total?done/total*100:100}%"></span></div></div>${items.length?`<div class="bag-items">${items.map(x=>{let checked=!!db.packed[s.id+'|'+d+'|'+x.id];return `<label class="check-row ${checked?'checked':''}"><input type="checkbox" data-bag="${E(s.id+'|'+d+'|'+x.id)}" ${checked?'checked':''} ${!allow?'disabled':''}><span class="custom-check">${ic('check',15)}</span><span dir="auto">${E(x.value)}</span></label>`}).join('')}</div>`:empty('noBag')}${done===total&&total?`<div class="complete-banner">${ic('check',21)}${txt(t('allPacked'))}</div>`:''}`}
function cardsFrom(s,types=['test','announcement','event','reminder','supplies']){let u=updatesFor(s).filter(u=>types.includes(u.type)&&u.due>=isoDate(-1)).sort((a,b)=>a.due.localeCompare(b.due));return u.length?u.slice(0,6).map(x=>updateCard(x)).join(''):empty('noUpdates')}
function studentHome(){let s=student(),h=homeworkFor(s).filter(u=>!completion(s,u)).sort((a,b)=>a.due.localeCompare(b.due)),[p,total]=packedCount(s);return `${greetingHeader(s.name,t('studentIntro'),button('ready','go:bag','primary','bag'))}<div class="student-hero"><div><div class="eyebrow hero-eyebrow">${txt(t('morning'))}</div><h2>${txt(t('today'))}<span class="hero-dot"></span></h2><p>${txt(t('studentIntro'))}</p><div class="hero-chips">${chip(nameClass(s.classId),'white')}${chip(date(isoDate()),'white')}</div></div><div class="hero-figure"><span class="hero-circle"><span class="line-graphic">${ic('book',66)}</span></span><span class="hero-small">${ic('check',28)}</span></div></div><div class="four-questions"><button data-action="go:timetable">${ic('timetable')}<span>${txt(t('todayClasses'))}</span><strong>${n(lessons(s.classId,weekday(isoDate())).length)}</strong></button><button data-action="go:bag">${ic('bag')}<span>${txt(t('needBring'))}</span><strong>${n(p)} / ${n(total)}</strong></button><button data-action="go:homework">${ic('homework')}<span>${txt(t('needDo'))}</span><strong>${n(h.length)}</strong></button><button data-action="go:week">${ic('reminder')}<span>${txt(t('remember'))}</span><strong>${n(updatesFor(s).filter(u=>u.type!=='homework'&&u.due>=isoDate()).length)}</strong></button></div><div class="dashboard-grid"><div class="stack">${section('todayClasses',timetable(s),`<button class="text-link" data-action="go:timetable">${txt(t('viewAll'))}${ic('arrow',16)}</button>`)}${section('homework',h.length?h.slice(0,3).map(u=>updateCard(u,s)).join(''):empty(),`<button class="text-link" data-action="go:homework">${txt(t('viewAll'))}${ic('arrow',16)}</button>`)}</div><div class="stack">${section('bag',bagList(s),`<button class="text-link" data-action="go:bag">${txt(t('viewAll'))}${ic('arrow',16)}</button>`)}${section('dontForget',cardsFrom(s))}</div></div>`}
function timetablePage(){let s=role==='student'?student():activeStudent();return `${header(t('timetable'),s.name+' · '+nameClass(s.classId))}<div class="day-picker">${[0,1,2,3,4,5,6].map(day=>`<button class="day-tab ${weekday(selectedDate)===day?'active':''}" data-action="day:${day}">${txt(t('dayShort')[day])}<span>${n(day)}</span></button>`).join('')}</div>${section('lessons',timetable(s,weekday(selectedDate)))}${section('dontForget',cardsFrom(s))}`}
function homeworkPage(){let s=role==='student'?student():activeStudent();let list=homeworkFor(s).sort((a,b)=>a.due.localeCompare(b.due));let [done,total]=countDone(s);return `${header(t('homework'),s.name+' · '+nameClass(s.classId))}<div class="stats-grid">${stat(total,'totalTasks','homework')}${stat(done,'complete','check','mint')}${stat(total-done,'open','clock','peach')}</div>${section('allHomework',list.length?list.map(u=>updateCard(u,role==='student'?s:null)).join(''):empty())}`}
function bagPage(){let s=role==='student'?student():activeStudent();return `${header(t('bag'),s.name+' · '+nameClass(s.classId))}<div class="two-col"><div>${section('today',bagList(s,isoDate(),role==='student'))}${role==='student'?`<form class="add-form" id="bag-form"><label>${txt(t('addExtra'))}<input name="item" maxlength="70" required placeholder="${E(t('addItemPlaceholder'))}"></label><button class="btn primary" type="submit">${ic('plus')}${txt(t('add'))}</button></form>`:''}</div><div>${section('tomorrowLabel',bagList(s,isoDate(1),role==='student'))}</div></div>`}
function weekPage(){let s=student();let dates=Array.from({length:7},(_,i)=>isoDate(i+weekOffset*7));return `${header(t('week'),t('weekHeadline'))}<div class="week-nav"><button data-action="weekPrev" class="icon-button" aria-label="${E(t('previous'))}">${ic('arrow')}</button><b>${date(dates[0])} — ${date(dates[6])}</b><button data-action="weekNext" class="icon-button" aria-label="${E(t('next'))}">${ic('arrow')}</button></div><div class="week-grid">${dates.map(d=>`<article class="week-day"><strong>${txt(t('weekDays')[weekday(d)])}</strong><small>${date(d)}</small><div class="week-count">${n(lessons(s.classId,weekday(d)).length)} ${txt(t('lessons'))}</div>${updatesFor(s).filter(u=>u.due===d).map(u=>`<div class="week-entry ${u.type}">${txt(t(u.subject))}<b dir="auto">${E(u.title)}</b></div>`).join('')||`<span class="no-entry">${txt(t('none'))}</span>`}</article>`).join('')}</div>`}
function progressRing(a,b,label){return `<div class="progress-ring-wrap"><div class="ring" style="--p:${b?Math.round(a/b*100):100}"><span>${n(b?Math.round(a/b*100):100)}%</span></div><div><h3>${txt(t(label))}</h3><p>${n(a)} / ${n(b)}</p></div></div>`}
function familyProgressCard(s){let [done,total]=countDone(s),[packed,bagtotal]=packedCount(s),homeworkPercent=total?Math.round(done/total*100):100,bagPercent=bagtotal?Math.round(packed/bagtotal*100):100;return `<article class="family-progress-card"><div class="family-progress-heading"><div><strong>${E(s.name)}</strong><small>${E(nameClass(s.classId))}</small></div><button class="text-link" data-action="child:${E(s.id)}:progress">${txt(t('viewProgress'))}${ic('arrow',16)}</button></div><div class="family-progress-metrics"><div><span>${txt(t('homeworkProgress'))}</span><strong>${n(done)} / ${n(total)}</strong><span class="progress-track"><span style="width:${homeworkPercent}%"></span></span></div><div><span>${txt(t('bagProgress'))}</span><strong>${n(packed)} / ${n(bagtotal)}</strong><span class="progress-track"><span style="width:${bagPercent}%"></span></span></div></div></article>`}
function progressPage(){if(role==='parent'){let kids=parent().studentIds.map(id=>db.students.find(s=>s.id===id)).filter(Boolean);return `${header(t('progress'),t('progressShared'))}<div class="family-progress-list">${kids.map(familyProgressCard).join('')||empty('noTasks')}</div>`}let s=student(),[done,total]=countDone(s),[packed,bagtotal]=packedCount(s);return `${header(t('progress'),t('progressInfo'))}<div class="two-col">${section('homeworkProgress',progressRing(done,total,'homeworkProgress'))}${section('bagProgress',progressRing(packed,bagtotal,'bagProgress'))}</div>${section('allDone',(done===total&&packed===bagtotal)?`<div class="complete-banner">${ic('check',20)}${txt(t('allDone'))}</div>`:`<p class="muted">${txt(t('progressInfo'))}</p>`)}`}
function childSelect(){return `<div class="child-switch"><label>${txt(t('chooseChild'))}<select id="child-select">${parent().studentIds.map(id=>{let x=db.students.find(s=>s.id===id);return `<option value="${id}" ${child===id?'selected':''}>${E(x.name)} · ${E(nameClass(x.classId))}</option>`}).join('')}</select></label></div>`}
function parentHome(){let kids=parent().studentIds.map(id=>db.students.find(x=>x.id===id)).filter(Boolean),all=kids.flatMap(s=>homeworkFor(s).filter(u=>!completion(s,u)).map(u=>({s,u}))).sort((a,b)=>a.u.due.localeCompare(b.u.due));return `${greetingHeader(parent().name,t('parentIntro'),button('ready','go:tomorrow','primary','calendar'))}<div class="parent-hero"><div><span class="eyebrow">${txt(t('family'))} · SCHOOL SIGNAL</span><h2>${txt(t('familyPriorities'))}</h2><p>${txt(t('parentIntro'))}</p></div><span class="parent-hero-icon">${ic('children',46)}</span></div><div class="stats-grid">${stat(kids.length,'children','children')}${stat(all.length,'open','homework','peach')}${stat(kids.reduce((a,s)=>a+updatesFor(s).filter(u=>u.type==='test'&&u.due>=isoDate()).length,0),'upcomingTests','test','sky')}</div><div class="dashboard-grid"><div class="stack">${section('children',kids.map(s=>`<button class="child-tile" data-action="child:${s.id}"><span class="avatar large">${E(s.name[0])}</span><span><b>${E(s.name)}</b><small>${E(nameClass(s.classId))}</small></span><span class="child-tasks">${n(homeworkFor(s).filter(u=>!completion(s,u)).length)} ${txt(t('open'))}</span>${ic('arrow')}</button>`).join(''))}${section('progress',kids.map(familyProgressCard).join('')||empty('noTasks'),button('viewProgress','go:progress','secondary'))}${section('homework',all.length?all.slice(0,5).map(({s,u})=>`<div class="child-record">${chip(s.name,'lavender')}${updateCard(u)}</div>`).join(''):empty())}</div><div class="stack">${section('tomorrow',kids.map(s=>{let [packed,total]=packedCount(s,isoDate(1));return `<button data-action="child:${s.id}:tomorrow" class="preparation-tile"><b>${E(s.name)}</b><span>${n(packed)} / ${n(total)} ${txt(t('packed'))}</span><span class="progress-track"><span style="width:${total?packed/total*100:100}%"></span></span></button>`}).join(''),`<button class="text-link" data-action="go:tomorrow">${txt(t('viewAll'))}${ic('arrow')}</button>`)}${section('recent',activeNotifications().slice(0,3).map(u=>updateCard(u)).join('')||empty())}</div></div>`}
function childrenPage(){return `${header(t('children'),t('parentIntro'))}<div class="child-grid">${parent().studentIds.map(id=>db.students.find(s=>s.id===id)).filter(Boolean).map(s=>`<button class="child-profile" data-action="child:${s.id}"><span class="avatar xl">${E(s.name[0])}</span><h2>${E(s.name)}</h2><p>${E(nameClass(s.classId))}</p><span class="chip lavender">${n(homeworkFor(s).filter(u=>!completion(s,u)).length)} ${txt(t('open'))}</span><span class="profile-action">${txt(t('viewChild'))}${ic('arrow')}</span></button>`).join('')}</div>`}
function childDetailPage(){let s=activeStudent();return `${header(s.name,t('childDetail')+' · '+nameClass(s.classId),childSelect())}<div class="stats-grid">${stat(lessons(s.classId,weekday(isoDate())).length,'todayClasses','timetable')}${stat(homeworkFor(s).filter(u=>!completion(s,u)).length,'open','homework')}${stat(updatesFor(s).filter(u=>u.type==='test'&&u.due>=isoDate()).length,'upcomingTests','test')}</div><div class="two-col">${section('todayClasses',timetable(s))}${section('homework',homeworkFor(s).slice(0,4).map(u=>updateCard(u)).join('')||empty())}${section('bag',bagList(s,isoDate(),false))}${section('dontForget',cardsFrom(s))}</div>`}
function announcementsPage(){let kids=parent().studentIds.map(id=>db.students.find(s=>s.id===id)).filter(Boolean),rows=activeNotifications().filter(u=>u.type!=='homework'&&(filterClass==='all'||u.classId===filterClass)&&(filterType==='all'||u.type===filterType));return `${header(t('announcements'),t('parentIntro'))}${filterBar(kids.map(s=>s.classId))}${section('recent',rows.length?rows.map(u=>updateCard(u)).join(''):empty('noResult'))}`}
function calendarPage(){let kids=parent().studentIds.map(id=>db.students.find(s=>s.id===id)).filter(Boolean);let rows=kids.flatMap(s=>updatesFor(s).map(u=>({s,u}))).filter(({u})=>u.due>=isoDate(-7)).sort((a,b)=>a.u.due.localeCompare(b.u.due));return `${header(t('calendar'),t('weekHeadline'))}<div class="calendar-list">${rows.map(({s,u})=>`<div class="calendar-row"><div class="date-tile"><b>${n(new Date(u.due+'T12:00:00').getDate())}</b><small>${new Intl.DateTimeFormat(locale(),{month:'short',numberingSystem:'latn'}).format(new Date(u.due+'T12:00:00'))}</small></div>${chip(s.name,'lavender')}<div><strong dir="auto">${E(u.title)}</strong><small>${txt(t(u.subject))} · ${txt(t(u.type==='supplies'?'suppliesType':u.type+'Type'))}</small></div></div>`).join('')||empty('noEvents')}</div>`}
function tomorrowPage(){let s=activeStudent();let open=homeworkFor(s).filter(u=>!completion(s,u));return `${header(t('tomorrow'),t('parentIntro'),childSelect())}<div class="tomorrow-banner">${ic('calendar',30)}<div><strong>${txt(t('tomorrowLabel'))}</strong><span>${date(isoDate(1))}</span></div></div><div class="two-col">${section('todayClasses',timetable(s,weekday(isoDate(1))))}${section('bag',bagList(s,isoDate(1),false))}${section('homework',open.length?open.map(u=>updateCard(u)).join(''):empty())}${section('dontForget',cardsFrom(s))}</div>`}
function teacherRows(){return db.updates.filter(u=>u.teacherId===person&&permitted(u.classId)).sort((a,b)=>b.created.localeCompare(a.created)||b.id.localeCompare(a.id))}function filterBar(cls=myClasses()){return `<div class="filter-bar"><label>${txt(t('classLabel'))}<select id="filter-class"><option value="all">${E(t('all'))}</option>${[...new Set(cls)].map(id=>`<option ${filterClass===id?'selected':''} value="${E(id)}">${E(nameClass(id))}</option>`).join('')}</select></label><label>${txt(t('type'))}<select id="filter-type"><option value="all">${E(t('all'))}</option>${['homework','test','announcement','event','supplies','reminder'].map(type=>`<option ${filterType===type?'selected':''} value="${type}">${E(t(type==='supplies'?'suppliesType':type+'Type'))}</option>`).join('')}</select></label></div>`}function filteredTeacherRows(homeOnly=false){return teacherRows().filter(u=>(!homeOnly||u.type==='homework')&&(filterClass==='all'||u.classId===filterClass)&&(filterType==='all'||u.type===filterType)&&(!query||(u.title+' '+u.description).toLowerCase().includes(query.toLowerCase())))}
function teacherHome(){let rows=teacherRows(),cls=myClasses();return `${greetingHeader(teacher().name,t('teacherIntro'),button('quickPublish','go:create','primary','plus'))}<div class="teacher-hero"><div><span class="eyebrow">SCHOOL SIGNAL · ${txt(t('teacher'))}</span><h2>${txt(t('teacherIntro'))}</h2><p>${txt(t('multiNote'))}</p>${button('create','go:create','white','plus')}</div><div class="teacher-illustration" aria-hidden="true"><div class="teacher-paper">${ic('calendar',36)}<span></span><span></span><span></span></div></div></div><div class="stats-grid">${stat(cls.length,'myClasses','classes')}${stat(rows.filter(x=>x.type==='homework').length,'teacherTasks','homework','sky')}${stat(rows.filter(x=>x.type==='test'&&x.due>=isoDate()).length,'upcomingTests','test','peach')}</div><div class="dashboard-grid"><div class="stack">${section('myClasses',cls.map(id=>classTile(id)).join(''),`<button class="text-link" data-action="go:classes">${txt(t('viewAll'))}${ic('arrow')}</button>`)}${section('schedule',cls.flatMap(id=>lessons(id,weekday(isoDate())).filter(l=>permitted(id,l.subject)).map(l=>`<div class="lesson-row"><div class="lesson-time" dir="ltr"><strong>${E(l.start)}</strong><small>${E(l.end)}</small></div>${subjectIcon(l.subject)}<div class="lesson-copy"><strong>${txt(t(l.subject))}</strong><small>${E(nameClass(id))}</small></div></div>`)).join('')||empty('noLessons'),`<button class="text-link" data-action="go:schedule">${txt(t('editSchedule'))}</button>`)}</div><div class="stack">${section('recent',rows.slice(0,6).map(u=>updateCard(u)).join('')||empty(),`<button class="text-link" data-action="go:history">${txt(t('viewAll'))}${ic('arrow')}</button>`)}</div></div>`}
function classTile(id){let a=assignments().filter(a=>a.classId===id),c=db.classes.find(c=>c.id===id),ups=teacherRows().filter(u=>u.classId===id);return `<button class="class-tile" data-action="class:${id}"><span class="class-graphic">${ic('classes',27)}</span><span class="class-info"><strong>${E(nameClass(id))}</strong><small>${a.map(a=>t(a.subject)).join(' · ')}</small></span><span class="class-count">${n(c?.count||0)} ${txt(t('students'))}<small>${n(ups.length)} ${txt(t('activity'))}</small></span>${ic('arrow')}</button>`}
function classesPage(){return `${header(t('classes'),t('teacherIntro'),button('create','go:create','primary','plus'))}<div class="class-list">${myClasses().map(id=>classTile(id)).join('')||empty('noClasses')}</div>`}
function classDetailPage(){if(!myClasses().includes(currentClass))currentClass=myClasses()[0];let assigned=assignments().filter(a=>a.classId===currentClass);return `${header(nameClass(currentClass),t('classDetail'),button('create','go:create','primary','plus'))}<div class="stats-grid">${stat(db.classes.find(c=>c.id===currentClass)?.count||0,'students','children')}${stat(assigned.length,'classSubjects','book')}${stat(teacherRows().filter(u=>u.classId===currentClass).length,'activity','announcements')}</div><div class="two-col">${section('classSubjects',assigned.map(a=>`<div class="lesson-row">${subjectIcon(a.subject)}<strong>${txt(t(a.subject))}</strong></div>`).join(''))}${section('todayClasses',lessons(currentClass,weekday(isoDate())).map(l=>`<div class="lesson-row"><div class="lesson-time" dir="ltr">${E(l.start)} – ${E(l.end)}</div>${subjectIcon(l.subject)}<strong>${txt(t(l.subject))}</strong></div>`).join('')||empty('noLessons'))}</div>${section('recent',teacherRows().filter(u=>u.classId===currentClass).map(u=>updateCard(u)).join('')||empty())}`}
function updateForm(){let original=db.updates.find(u=>u.id===editing),isEdit=!!original,cls=myClasses();if(!cls.length)return empty('noClasses');let selected=original?[original.classId]:[currentClass&&cls.includes(currentClass)?currentClass:cls[0]];return `${header(t(isEdit?'edit':'create'),t('multiNote'))}<form id="update-form" class="editor-form"><div class="form-column"><div class="panel form-panel"><h2>${txt(t('selectClasses'))}</h2><div class="class-pills">${cls.map(id=>`<label class="class-check"><input name="classes" type="checkbox" value="${id}" ${selected.includes(id)?'checked':''} ${isEdit?'disabled':''}><span>${E(nameClass(id))}</span></label>`).join('')}</div>${isEdit?`<input type="hidden" name="classes" value="${E(original.classId)}">`:''}<div class="form-grid"><label>${txt(t('type'))}<select name="type" required>${['homework','test','announcement','event','supplies','reminder'].map(x=>`<option value="${x}" ${original?.type===x?'selected':''}>${E(t(x==='supplies'?'suppliesType':x+'Type'))}</option>`).join('')}</select></label><label>${txt(t('subject'))}<select name="subject" required>${[...new Set(assignments().map(a=>a.subject))].map(x=>`<option value="${x}" ${original?.subject===x?'selected':''}>${E(t(x))}</option>`).join('')}</select></label></div><label>${txt(t('title'))}<input name="title" maxlength="120" required value="${E(original?.title||'')}" placeholder="${E(t('title'))}"></label><label>${txt(t('description'))}<textarea name="description" rows="5" required maxlength="1200" placeholder="${E(t('description'))}">${E(original?.description||'')}</textarea></label><div class="form-grid"><label>${txt(t('dueDate'))}<input name="due" type="date" required value="${E(original?.due||isoDate(2))}"></label><label>${txt(t('status'))}<select name="status"><option value="published" ${original?.status!=='draft'?'selected':''}>${E(t('published'))}</option><option value="draft" ${original?.status==='draft'?'selected':''}>${E(t('draft'))}</option></select></label></div><label>${txt(t('supplies'))} <small>${txt(t('optional'))}</small><input name="supplies" value="${E((original?.supplies||[]).join(', '))}" placeholder="${E(t('supplyHelp'))}"></label><small class="form-help">${txt(t('supplyHelp'))}</small><p id="form-error" role="alert" class="form-error" hidden></p><div class="form-actions"><button type="submit" class="btn primary">${ic('check')}${txt(t(isEdit?'save':'publish'))}</button>${button('cancel','go:history','ghost')}${isEdit?button('delete','delete:'+original.id,'danger','trash'):''}</div></div></div><aside class="editor-aside"><div class="aside-card">${ic('shield',28)}<h3>${txt(t('scope'))}</h3><p>${txt(t('multiNote'))}</p><hr><p>${txt(t('demoNote'))}</p></div></aside></form>`}
function historyPage(homeOnly=false){let rows=filteredTeacherRows(homeOnly);return `${header(t(homeOnly?'manage':'history'),t('historyCaption'),button('create','go:create','primary','plus'))}<div class="panel manage-panel">${filterBar()}<label class="search-wrap">${ic('filter',20)}<input id="update-search" value="${E(query)}" placeholder="${E(t('searchPlaceholder'))}" aria-label="${E(t('search'))}"></label><div id="results-list">${rows.length?rows.map(u=>updateCard(u)).join(''):empty('noResult')}</div></div>`}
function schedulePage(){let cls=myClasses();if(!cls.includes(currentClass))currentClass=cls[0];let allowedSubjects=assignments().filter(a=>a.classId===currentClass).map(a=>a.subject);let l=editLesson?db.lessons.find(x=>x.id===editLesson):null;return `${header(t('schedule'),t('editSchedule'))}<div class="filter-bar"><label>${txt(t('classLabel'))}<select id="schedule-class">${cls.map(id=>`<option value="${id}" ${id===currentClass?'selected':''}>${E(nameClass(id))}</option>`).join('')}</select></label></div><div class="schedule-layout"><div class="panel form-panel"><h2>${txt(t(l?'editLesson':'addLesson'))}</h2><form id="lesson-form" class="lesson-form"><label>${txt(t('day'))}<select name="day">${[0,1,2,3,4,5].map(day=>`<option value="${day}" ${l?.day===day?'selected':''}>${E(t('weekDays')[day])}</option>`).join('')}</select></label><label>${txt(t('subject'))}<select name="subject">${allowedSubjects.map(x=>`<option value="${x}" ${l?.subject===x?'selected':''}>${E(t(x))}</option>`).join('')}</select></label><div class="form-grid"><label>${txt(t('start'))}<input type="time" required name="start" value="${E(l?.start||'12:30')}"></label><label>${txt(t('end'))}<input type="time" required name="end" value="${E(l?.end||'13:15')}"></label></div><label>${txt(t('room'))}<input name="room" maxlength="40" value="${E(l?.room||'')}"></label><p id="lesson-error" role="alert" class="form-error" hidden></p><button type="submit" class="btn primary">${ic('check')}${txt(t('saveLesson'))}</button>${l?button('cancel','cancelLesson','ghost'):''}</form></div><div class="panel"><h2>${txt(t('weekOverview'))}</h2>${[0,1,2,3,4,5].map(day=>`<div class="schedule-day"><h3>${txt(t('weekDays')[day])}</h3>${lessons(currentClass,day).filter(x=>permitted(currentClass,x.subject)).map(x=>`<div class="schedule-item">${subjectIcon(x.subject)}<span><strong>${txt(t(x.subject))}</strong><small dir="ltr">${E(x.start)} – ${E(x.end)}</small></span><button class="icon-button" data-action="lessonEdit:${x.id}" aria-label="${E(t('editLesson'))}">${ic('editIcon',17)}</button><button class="icon-button destructive" data-action="lessonDelete:${x.id}" aria-label="${E(t('deleteLesson'))}">${ic('trash',17)}</button></div>`).join('')||`<p class="muted">${txt(t('daysOff'))}</p>`}</div>`).join('')}</div></div>`}
function notificationsPage(){let rows=activeNotifications();return `${header(t('notifications'),t('notificationsHelp'),role==='teacher'?'':button('allRead','markAll','secondary','check'))}${section('recent',rows.length?rows.map(u=>`<div class="notification-row"><span class="notification-icon">${ic(u.type,21)}</span><div><strong dir="auto">${E(u.title)}</strong><p>${txt(t(u.type==='supplies'?'suppliesType':u.type+'Type'))} · ${E(nameClass(u.classId))}</p></div>${role!=='teacher'&&!db.read[person+'|'+u.id]?`<button class="btn secondary" data-action="markRead:${u.id}">${txt(t('read'))}</button>`:chip(t('readStatus'),'plain')}</div>`).join(''):empty('emptyNotifications'))}`}
function languagePage(){return `${header(t('language'),t('languageDesc'))}<div class="panel form-panel"><div class="language-options">${Object.entries({ar:'العربية',he:'עברית',en:'English'}).map(([key,label])=>`<button class="language-choice ${db.settings.language===key?'selected':''}" data-action="lang:${key}"><span lang="${key}" dir="${key==='en'?'ltr':'rtl'}">${label}</span>${db.settings.language===key?ic('check',22):''}</button>`).join('')}</div></div>`}
function setupPage(){const classOptions=db.classes.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join(''),studentOptions=db.students.map(s=>`<option value="${E(s.id)}">${E(s.name)} · ${E(nameClass(s.classId))}</option>`).join('');return `<div class="public"><header class="public-bar"><div class="logo static-logo"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span></span></div><select id="lang-select" aria-label="${E(t('language'))}" class="compact-select">${Object.entries({ar:'العربية',he:'עברית',en:'English'}).map(([k,v])=>`<option value="${k}" ${db.settings.language===k?'selected':''}>${v}</option>`).join('')}</select></header><main class="public-center onboarding"><span class="eyebrow">${txt(db.school.name||st('setupTitle'))}</span><h1>${txt(st('setupTitle'))}</h1><p>${txt(st('setupIntro'))}</p><form id="school-form" class="panel form-panel"><label>${txt(st('schoolName'))}<input name="name" maxlength="100" required value="${E(db.school.name)}"></label><button class="btn primary" type="submit">${txt(st('saveSchool'))}</button></form><div class="setup-forms"><form id="class-form" class="panel form-panel"><h2>${txt(st('addClass'))}</h2><label>${txt(st('className'))}<input name="name" maxlength="40" required></label><label>${txt(st('grade'))}<input name="grade" type="number" min="1" max="12" value="1" required></label><button class="btn secondary" type="submit">${txt(st('addClass'))}</button></form>${db.classes.length?`<form id="teacher-form" class="panel form-panel"><h2>${txt(st('addTeacher'))}</h2><label>${txt(st('teacherName'))}<input name="name" maxlength="80" required></label><label>${txt(st('selectClass'))}<select name="classId" required>${classOptions}</select></label><label>${txt(t('subject'))}<select name="subject" required>${db.subjects.map(s=>`<option value="${E(s)}">${E(t(s))}</option>`).join('')}</select></label><button class="btn secondary" type="submit">${txt(st('addTeacher'))}</button></form><form id="student-form" class="panel form-panel"><h2>${txt(st('addStudent'))}</h2><label>${txt(st('studentName'))}<input name="name" maxlength="80" required></label><label>${txt(st('selectClass'))}<select name="classId" required>${classOptions}</select></label><button class="btn secondary" type="submit">${txt(st('addStudent'))}</button></form>`:''}${db.students.length?`<form id="parent-form" class="panel form-panel"><h2>${txt(st('addParent'))}</h2><label>${txt(st('parentName'))}<input name="name" maxlength="80" required></label><label>${txt(st('selectStudent'))}<select name="studentId" required>${studentOptions}</select></label><button class="btn secondary" type="submit">${txt(st('addParent'))}</button></form>`:''}</div>${[db.students,db.parents,db.teachers].some(list=>list.length)?button('choose','go:choose','primary','arrow'):''}<div class="form-actions">${demoOn()?button('removeDemo','clearDemo','danger','trash'):button('restoreDemo','restoreDemo','secondary','users')}</div></main></div>`}
function profilePage(){return `<div class="public"><header class="public-bar"><div class="logo static-logo"><span class="signal-mark"><i></i><i></i><i></i></span><span class="wordmark">SCHOOL<span>SIGNAL</span></span></div>${button('back','go:choose','ghost')}</header><div class="public-center onboarding"><span class="eyebrow">${txt(db.school.name)}</span><h1>${txt(t(role))}</h1><p>${txt(t('chooseSub'))}</p><div class="panel form-panel"><label>${txt(t('profile'))}<select id="person-select">${people().map(p=>`<option value="${E(p.id)}" ${person===p.id?'selected':''}>${E(p.name)}${p.classId?' · '+nameClass(p.classId):''}</option>`).join('')}</select></label>${button('continue','start','primary','arrow')}</div></div></div>`}
function settingsPage(){return `${header(t('settings'),t('settingsIntro'))}${section('profile',`<div class="setting-row"><span>${txt(t('profile'))}</span><strong>${E(people().find(u=>u.id===person)?.name||'')}</strong></div><div class="setting-row"><span>${txt(t('language'))}</span><button class="btn secondary" data-action="go:language">${txt(({ar:'العربية',he:'עברית',en:'English'})[db.settings.language])}</button></div><label class="setting-row"><span>${txt(t('reduceMotion'))}</span><input type="checkbox" id="motion-toggle" ${db.settings.reducedMotion?'checked':''}></label><div class="form-actions">${button('manageSchool','go:setup','secondary','edit')}</div>`)}${demoOn()?section('demo',`<p class="muted">${txt(t('demoNote'))}</p><div class="form-actions">${button('switchDemo','switch','secondary','users')}${button('reset','reset','secondary','trash')}${button('removeDemo','clearDemo','danger','trash')}</div>`):''}`}
function helpPage(){return `${header(t('help'),t('helpTitle'))}<div class="help-grid">${['student','parent','teacher'].map(r=>`<div class="panel help-item"><span class="role-symbol role-${r}">${ic(r,27)}</span><h2>${txt(t(r))}</h2><p>${txt(t('help'+r[0].toUpperCase()+r.slice(1)))}</p></div>`).join('')}</div>${section('helpGuide',`<div class="soft-info">${ic('shield',24)}<p>${txt(t('helpPrivacy'))}</p></div>`)}`}
function render(){let lang=db.settings.language;document.documentElement.lang=lang;document.documentElement.dir='ltr';document.body.classList.toggle('reduce-motion',db.settings.reducedMotion);document.body.classList.toggle('no-demo',!demoOn());document.title='SCHOOL SIGNAL — '+t('brand');if(screen==='setup'||(!demoOn()&&screen==='welcome'))el.innerHTML=setupPage();else if(!role||['welcome','choose','onboarding'].includes(screen))el.innerHTML=screen==='onboarding'&&!demoOn()?profilePage():publicPage();else{let content=role==='student'?({home:studentHome,timetable:timetablePage,homework:homeworkPage,bag:bagPage,week:weekPage,progress:progressPage}[screen]):role==='parent'?({home:parentHome,children:childrenPage,childDetail:childDetailPage,homework:homeworkPage,announcements:announcementsPage,calendar:calendarPage,tomorrow:tomorrowPage}[screen]):({home:teacherHome,classes:classesPage,classDetail:classDetailPage,create:updateForm,edit:updateForm,manage:()=>historyPage(true),schedule:schedulePage,history:historyPage}[screen]);content=content||({progress:progressPage,settings:settingsPage,language:languagePage,notifications:notificationsPage,help:helpPage}[screen])||(()=>header(t('home')));el.innerHTML=shell(content())}document.querySelector('#content h1')?.setAttribute('tabindex','-1')}
function failed(id,msg){let field=document.getElementById(id);if(field){field.hidden=false;field.textContent=msg}notice('error',msg)}
function submitUpdate(form){let f=new FormData(form),classes=[...new Set(f.getAll('classes'))],subject=f.get('subject'),title=String(f.get('title')||'').trim(),description=String(f.get('description')||'').trim(),due=f.get('due'),type=f.get('type'),status=f.get('status'),supplies=String(f.get('supplies')||'').split(',').map(s=>s.trim()).filter(Boolean);if(!classes.length)return failed('form-error',t('selectOne'));if(!title||!description||!due)return failed('form-error',t('formError'));if(!/^\d{4}-\d{2}-\d{2}$/.test(due))return failed('form-error',t('dateError'));if(classes.some(cl=>!permitted(cl,subject)))return failed('form-error',t('wrongClass'));if(editing){let old=db.updates.find(u=>u.id===editing);if(!old||old.teacherId!==person||!permitted(old.classId))return failed('form-error',t('permissionError'));Object.assign(old,{subject,title,description,due,type,supplies,status,modified:isoDate()})}else{let group='g'+db.nextId++;for(const cl of classes){db.updates.push({id:'u'+db.nextId++,groupId:group,classId:cl,teacherId:person,subject,title,description,due,type,supplies,status,created:isoDate(),modified:isoDate()})}}save();editing='';query='';filterClass='all';filterType='all';go('history');notice('success',status==='draft'?t('unpublished'):t('success'))}
function submitLesson(form){const f=new FormData(form),day=Number(f.get('day')),subject=f.get('subject'),start=f.get('start'),end=f.get('end'),room=String(f.get('room')||'').trim();if(!permitted(currentClass,subject))return failed('lesson-error',t('wrongClass'));if(end<=start)return failed('lesson-error',t('invalidTime'));if(db.lessons.some(l=>l.classId===currentClass&&l.day===day&&l.id!==editLesson&&start<l.end&&end>l.start))return failed('lesson-error',t('lessonConflict'));if(editLesson){let original=db.lessons.find(l=>l.id===editLesson);if(!original||!permitted(original.classId,original.subject))return failed('lesson-error',t('permissionError'));Object.assign(original,{day,subject,start,end,room,teacherId:person})}else db.lessons.push({id:'l'+db.nextId++,classId:currentClass,day,subject,start,end,room,teacherId:person});editLesson='';save();render();notice('success',t('success'))}
function handleAction(action){let [verb,...params]=action.split(':');if(verb==='go'){if(params[0]==='create')editing='';if(params[0]==='homework'&&role==='teacher')return go('manage');return go(params[0])}if(verb==='selectRole'){role=params[0];person=people()[0].id;go('onboarding');return}if(verb==='start'){switchRole(role,person);return}if(verb==='switch'){role='';person='';screen='choose';sessionStorage.removeItem('ss-role');sessionStorage.removeItem('ss-person');go('choose');return}if(verb==='child'){child=params[0];sessionStorage.setItem('ss-child',child);go(params[1]||'childDetail');return}if(verb==='class'){currentClass=params[0];go('classDetail');return}if(verb==='day'){let current=weekday(selectedDate),delta=(Number(params[0])-current+7)%7;selectedDate=isoDate(delta);render();return}if(verb==='weekPrev'||verb==='weekNext'){weekOffset+=verb==='weekPrev'?-1:1;render();return}if(verb==='complete'){let s=db.students.find(s=>s.id===params[0]);let u=db.updates.find(u=>u.id===params[1]);if(role!=='student'||s?.id!==person||u?.classId!==s.classId||u?.type!=='homework'||u.status!=='published')return notice('error',t('permissionError'));let key=s.id+'|'+u.id;db.completions[key]=!db.completions[key];save();render();return}if(verb==='edit'){let u=db.updates.find(x=>x.id===params[0]);if(role!=='teacher'||u?.teacherId!==person||!permitted(u.classId))return notice('error',t('permissionError'));editing=u.id;go('edit');return}if(verb==='delete'){let u=db.updates.find(x=>x.id===params[0]);if(role!=='teacher'||u?.teacherId!==person||!permitted(u.classId))return notice('error',t('permissionError'));if(confirm(t('confirmDelete'))){db.updates=db.updates.filter(x=>x.id!==u.id);for(const k in db.completions)if(k.endsWith('|'+u.id))delete db.completions[k];save();editing='';go('history');notice('success',t('deleted'))}return}if(verb==='lessonEdit'){let l=db.lessons.find(x=>x.id===params[0]);if(role!=='teacher'||!l||!permitted(l.classId,l.subject))return notice('error',t('permissionError'));currentClass=l.classId;editLesson=l.id;render();return}if(verb==='lessonDelete'){let l=db.lessons.find(x=>x.id===params[0]);if(role!=='teacher'||!l||!permitted(l.classId,l.subject))return notice('error',t('permissionError'));if(confirm(t('confirmLessonDelete'))){db.lessons=db.lessons.filter(x=>x.id!==l.id);save();render();notice('success',t('deleted'))}return}if(verb==='cancelLesson'){editLesson='';render();return}if(verb==='lang'){db.settings.language=params[0];save();render();return}if(verb==='reset'){if(confirm(t('confirmReset'))){let lang=db.settings.language;db=createSeed();db.settings.language=lang;save();render();notice('success',t('resetDone'))}return}if(verb==='markRead'){if(role==='teacher')return;db.read[person+'|'+params[0]]=true;save();render();return}if(verb==='markAll'){activeNotifications().forEach(u=>db.read[person+'|'+u.id]=true);save();render();return}}
window.addEventListener('click',e=>{let target=e.target.closest('[data-action]');if(!target)return;handleAction(target.dataset.action)});
window.addEventListener('change',e=>{let x=e.target;if(x.id==='lang-select'){db.settings.language=x.value;save();render()}else if(x.id==='person-select'){person=x.value}else if(x.id==='child-select'){child=x.value;sessionStorage.setItem('ss-child',child);render()}else if(x.id==='filter-class'){filterClass=x.value;render()}else if(x.id==='filter-type'){filterType=x.value;render()}else if(x.id==='schedule-class'){currentClass=x.value;editLesson='';render()}else if(x.id==='motion-toggle'){db.settings.reducedMotion=x.checked;save();render()}else if(x.dataset.bag){if(role!=='student'||!x.dataset.bag.startsWith(person+'|'))return;db.packed[x.dataset.bag]=x.checked;save();render()}});
window.addEventListener('input',e=>{if(e.target.id==='update-search'){let sel=e.target.selectionStart;query=e.target.value;let result=document.getElementById('results-list');if(result){let rows=filteredTeacherRows(screen==='manage');result.innerHTML=rows.length?rows.map(u=>updateCard(u)).join(''):empty('noResult')}e.target.setSelectionRange(sel,sel)}});
window.addEventListener('submit',e=>{if(e.target.id==='update-form'){e.preventDefault();submitUpdate(e.target)}else if(e.target.id==='lesson-form'){e.preventDefault();submitLesson(e.target)}else if(e.target.id==='bag-form'){e.preventDefault();if(role!=='student')return;let str=new FormData(e.target).get('item')?.trim();if(!str)return;let key=person+'|'+isoDate();db.extraBag??={};db.extraBag[key]??=[];if(!db.extraBag[key].some(x=>x.toLowerCase()===str.toLowerCase()))db.extraBag[key].push(str);save();render();notice('success',t('success'))}});
function saveSetup(next){if(!storageSave(next)){notice('error',t('saveError'));return}db=next;render();notice('success',st('setupComplete'))}
window.addEventListener('submit',e=>{const form=e.target;if(!['school-form','class-form','teacher-form','student-form','parent-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form),next=structuredClone(db),name=String(f.get('name')||'').trim();if(form.id==='school-form'){if(!name)return;next.school.name=name}else if(form.id==='class-form'){const grade=Number(f.get('grade'));if(!name||!Number.isInteger(grade)||grade<1||grade>12)return;if(next.classes.some(c=>c.name.toLowerCase()===name.toLowerCase()))return notice('error',t('formError'));next.classes.push({id:'c'+next.nextId++,name,grade,count:0})}else if(form.id==='teacher-form'){const classId=String(f.get('classId')||''),subject=String(f.get('subject')||'');if(!name||!next.classes.some(c=>c.id===classId)||!next.subjects.includes(subject))return notice('error',t('formError'));next.teachers.push({id:'t'+next.nextId++,name,assignments:[{classId,subject}]})}else if(form.id==='student-form'){const classId=String(f.get('classId')||''),cl=next.classes.find(c=>c.id===classId);if(!name||!cl)return notice('error',t('formError'));next.students.push({id:'s'+next.nextId++,name,classId});cl.count++}else{const studentId=String(f.get('studentId')||'');if(!name||!next.students.some(s=>s.id===studentId))return notice('error',t('formError'));next.parents.push({id:'p'+next.nextId++,name,studentIds:[studentId]})}saveSetup(next)});
window.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(action==='clearDemo'){e.preventDefault();e.stopImmediatePropagation();if(!confirm(st('confirmRemoveDemo')))return;const next=createBlankSchool(db.settings.language);if(!storageSave(next))return notice('error',t('saveError'));db=next;role='';person='';child='';sessionStorage.removeItem('ss-role');sessionStorage.removeItem('ss-person');sessionStorage.removeItem('ss-child');sessionStorage.setItem('ss-screen','setup');screen='setup';render();notice('success',st('demoRemoved'));return}if(action==='restoreDemo'){e.preventDefault();e.stopImmediatePropagation();if(!confirm(t('confirmReset')))return;const next=createSeed();next.settings.language=db.settings.language;if(!storageSave(next))return notice('error',t('saveError'));db=next;role='';person='';sessionStorage.removeItem('ss-role');sessionStorage.removeItem('ss-person');sessionStorage.setItem('ss-screen','welcome');screen='welcome';render();notice('success',t('resetDone'));return}if(action==='go:choose'&&!db.school.name.trim()){e.preventDefault();e.stopImmediatePropagation();notice('error',st('schoolRequired'));return}if(action.startsWith('selectRole:')){const requested=action.split(':')[1],available=requested==='student'?db.students:requested==='parent'?db.parents:db.teachers;if(!available.length){e.preventDefault();e.stopImmediatePropagation();role=requested;go('setup')}}},true);
if(!role&&screen!=='setup')screen='welcome';else if(role&&screen!=='setup'&&!menus[role]?.includes(screen)&&!['settings','language','notifications','help'].includes(screen))screen='home';render();
